document.addEventListener("DOMContentLoaded",()=>{const e=[{title:"Raw Materials",description:"Scrap bell metal or a careful mixture of copper and tin is gathered. The exact ratio determines the resonance, durability, and color of the final product.",image:"assets/culture.png"},{title:"Melting",description:"The metal is placed in graphite crucibles and melted in traditional earthen furnaces reaching extreme temperatures using coal or wood.",image:"assets/travel_hidden.png"},{title:"Mould Preparation",description:"For casting, clay or sand moulds are prepared. In the lost-wax (Dhokra) technique, a wax model is created, covered in clay, and then the wax is melted out.",image:"assets/heritage_temples.png"},{title:"Casting",description:"The molten bell metal is carefully poured into the hollow cavity of the mould, where it takes the shape of the negative space.",image:"assets/travel_mountains.png"},{title:"Cooling & Beating",description:"The metal is left to cool and solidify. In forging techniques (like in Sarthebari), the hot metal is repeatedly beaten into shape with heavy hammers.",image:"assets/travel_deserts.png"},{title:"Finishing",description:"Once cooled, the mould is broken (if lost-wax) or the item is taken out. Rough edges are filed, and intricate carvings or engravings may be added.",image:"assets/hero_banner.png"},{title:"Polishing",description:"The final craft is rigorously polished using sand, tamarind water, or modern buffers to achieve its signature golden-bronze gleam.",image:"assets/heritage_forts.png"}];let t=0;const i=document.getElementById("process-visualizer");!function n(){if(!i)return;let s="";e.forEach((e,i)=>{s+=`\n                <div class="step-container ${i===t?"active":""}" id="step-${i}">\n                    <div class="step-number">${i+1}</div>\n                    <h3 style="color: var(--text-light); margin-bottom: 15px; font-size: 1.6rem;">${e.title}</h3>\n                    <img src="${e.image}" alt="${e.title}" class="step-image" onerror="this.style.display='none'">\n                    <p style="color: var(--text-muted); font-size: 1.05rem; line-height: 1.6; max-width: 600px; margin: 0 auto;">${e.description}</p>\n                </div>\n            `}),s+=`\n            <div class="step-controls">\n                <button class="btn-step" id="prev-step" ${0===t?"disabled":""}>← Previous</button>\n                <div class="progress-dots">\n                    ${e.map((e,i)=>`<span class="progress-dot ${i===t?"active":""}"></span>`).join("")}\n                </div>\n                <button class="btn-step" id="next-step" ${t===e.length-1?"disabled":""}>Next →</button>\n            </div>\n        `,i.innerHTML=s;const a=document.getElementById("prev-step"),r=document.getElementById("next-step");a&&a.addEventListener("click",()=>{t>0&&(t--,n())}),r&&r.addEventListener("click",()=>{t<e.length-1&&(t++,n())})}();const n=[{name:"Xorai",region:"Assam",description:"A traditional offering tray with a stand, often with a lid. It is a symbol of Assamese culture, used to offer betel nuts or prasad.",image:"assets/culture.png"},{name:"Dhokra Figurine",region:"Chhattisgarh",description:"Intricate, rustic figurines made using the lost-wax casting technique. Common themes include tribal deities, horses, and elephants.",image:"assets/travel_hidden.png"},{name:"Temple Bell (Ghanta)",region:"Odisha",description:"Large, resonant bells cast for temples. The specific alloy composition ensures a deep, lingering sound.",image:"assets/heritage_temples.png"},{name:"Bata",region:"Assam",description:"A small, deep bowl used for serving areca nuts and betel leaves to guests.",image:"assets/travel_mountains.png"}],s=[{title:"Health & Ayurveda",description:"Eating and drinking from bell metal utensils is considered highly beneficial in Ayurveda for balancing the doshas and improving digestion.",image:"assets/travel_deserts.png"},{title:"Religious Rituals",description:"Its resonance makes it the prime material for bells and cymbals used in religious chants and ceremonies across India.",image:"assets/hero_banner.png"},{title:"Cultural Gifting",description:"In many regions, gifting bell metal utensils (like the Xorai in Assam) to a bride or a distinguished guest is a sign of immense respect.",image:"assets/heritage_forts.png"}],a=document.getElementById("details-modal"),r=document.getElementById("modal-title"),o=document.getElementById("modal-subtitle"),l=document.getElementById("modal-desc"),d=document.getElementById("close-modal");d&&d.addEventListener("click",()=>{a.classList.remove("active")}),a&&a.addEventListener("click",e=>{e.target===a&&a.classList.remove("active")});const c=document.getElementById("product-gallery");c&&n.forEach(e=>{const t=document.createElement("div");t.className="interactive-card",t.innerHTML=`\n                <img src="${e.image}" alt="${e.name}" class="product-image" onerror="this.style.display='none'">\n                <h3>${e.name}</h3>\n                <p style="color: var(--text-muted); font-size: 0.85rem; margin-top: auto;">Click to view details</p>\n            `,t.addEventListener("click",()=>{var t,i,n;t=e.name,i=e.region,n=e.description,r.textContent=t,o.textContent=i?`Region: ${i}`:"",l.textContent=n,a.classList.add("active")}),c.appendChild(t)});const m=document.getElementById("traditional-uses");m&&s.forEach(e=>{const t=document.createElement("div");t.className="interactive-card",t.style.cursor="default",t.innerHTML=`\n                <img src="${e.image}" alt="${e.title}" class="product-image" onerror="this.style.display='none'">\n                <h3>${e.title}</h3>\n                <p style="color: var(--text-light); font-size: 0.95rem; line-height: 1.6;">${e.description}</p>\n            `,m.appendChild(t)})});